/* Shared lightweight button hints: hover, keyboard focus and touch hold. */
(function(){
 const messages={cfSettings:'Configure schedule, access, response rules and Thank You page',cfAdd:'Insert the selected question type into the selected section',cfSection:'Add a new named section at the end of this form',cfIntroPdf:'Attach a PDF under the form title',cfIntroImage:'Attach an image under the form title',cfIntroLink:'Add a clickable link under the form title',cfSave:'Save the form title, fields, settings and rules',cfX:'Discard unsaved changes and close the editor',qrDl:'Download the entire verified poster in high-resolution PNG',qrSVG:'Download the entire verified vector poster',qrPrint:'Print the entire verified poster or save as PDF',qrX:'Close QR customization',gridEdit:'Enable spreadsheet cell editing',gridSave:'Save changes to response records',gridCancel:'Discard unsaved response edits',responseRefresh:'Load the latest responses now',sheetCopy:'Copy the selected cell range',sheetPaste:'Paste into the selected cells',sheetUndo:'Undo the last unsaved change',sheetRedo:'Redo an unsaved change',expCo:'Export all or filtered responses to Excel',adAdd:'Create an administrator account',manageAdmins:'View and manage administrator accounts',sectionNext:'Continue to the next visible section',sectionBack:'Return to the previous section',mediaDownload:'Download the original cached attachment',mediaShare:'Share the document or image',mediaClose:'Close preview and return to the form',scanBtn:'Scan a participant barcode using the camera',submit:'Submit the form response',nextBtn:'Start another response'};
 const labels={'Edit Form':'Edit questions, sections, descriptions and settings','QR Code':'Customize and download the QR poster','QR code':'Customize and download the QR poster','Share Link':'View, copy or customize the form link','Close Form':'Stop accepting responses','Reopen Form':'Allow responses according to the schedule','Edit':'Edit this entry','Delete':'Delete this entry (confirmation required)'};
 const tip=document.createElement('div');tip.id='lcTip';tip.setAttribute('role','tooltip');tip.hidden=true;tip.style.cssText='position:fixed;z-index:99999;max-width:min(260px,90vw);background:#192f4d;color:white;padding:8px 11px;border-radius:7px;font:13px Calibri,Arial,sans-serif;pointer-events:none;box-shadow:0 4px 12px #0003';document.body.append(tip);
 let timer,active;const button=e=>e.target.closest?.('button,[role=button]');const text=b=>b?.title||messages[b?.id]||labels[b?.textContent.trim()]||b?.getAttribute('aria-label')||b?.textContent.trim();
 function show(b){const t=text(b);if(!t)return;active=b;tip.textContent=t;tip.hidden=false;const r=b.getBoundingClientRect();tip.style.left=Math.max(8,Math.min(r.left,innerWidth-tip.offsetWidth-8))+'px';tip.style.top=Math.max(8,r.top>tip.offsetHeight+10?r.top-tip.offsetHeight-7:Math.min(innerHeight-tip.offsetHeight-8,r.bottom+7))+'px';b.setAttribute('aria-describedby','lcTip')}
 function hide(){clearTimeout(timer);tip.hidden=true;active?.removeAttribute('aria-describedby');active=null}
 document.addEventListener('pointerover',e=>{const b=button(e);if(b&&e.pointerType!=='touch'){clearTimeout(timer);timer=setTimeout(()=>show(b),400)}});document.addEventListener('pointerout',e=>{const b=button(e);if(b&&!b.contains(e.relatedTarget))hide()});document.addEventListener('focusin',e=>{const b=button(e);if(b)show(b)});document.addEventListener('focusout',hide);document.addEventListener('pointerdown',e=>{const b=button(e);if(b&&e.pointerType==='touch'){hide();timer=setTimeout(()=>show(b),500)}});document.addEventListener('pointerup',()=>{clearTimeout(timer);if(active)timer=setTimeout(hide,1800)});document.addEventListener('pointercancel',hide);document.addEventListener('scroll',hide,true);document.addEventListener('click',hide);
})();
